import SwiftUI
import MusicKit

/// In-app music: browse your library, search Apple Music, play without leaving the scene.
///
/// This replaces the old "open the Music app" button, which was the wrong shape for Float:
/// launching another app tears down the full immersive space (visionOS makes it exclusive),
/// so choosing a song meant leaving deep space and coming back. `ApplicationMusicPlayer` plays
/// inside *this* process, so the scene never goes away.
///
/// SETUP THIS CODE CANNOT DO FOR ITSELF: the App ID needs the **MusicKit** capability enabled
/// at developer.apple.com (Certificates, Identifiers & Profiles → the Ash4d.Float identifier →
/// App Services → MusicKit). Without it authorization is granted but every request comes back
/// empty or unauthorized. `NSAppleMusicUsageDescription` in Info.plist is the other half and
/// IS handled here.
@MainActor
@Observable
final class MusicModel {
    var status: MusicAuthorization.Status = MusicAuthorization.currentStatus
    var playlists: MusicItemCollection<Playlist> = []
    var albums: MusicItemCollection<Album> = []
    var searchResults: MusicItemCollection<Song> = []
    var loading = false
    var errorText: String?

    /// Shared, because it is the queue the system's Now Playing controls talk to. A second
    /// player instance would fight this one for the audio session.
    private let player = ApplicationMusicPlayer.shared

    var isPlaying: Bool { player.state.playbackStatus == .playing }
    var nowPlayingTitle: String? { player.queue.currentEntry?.title }
    var nowPlayingSubtitle: String? { player.queue.currentEntry?.subtitle }

    func requestAuthorization() async {
        status = await MusicAuthorization.request()
        if status == .authorized { await loadLibrary() }
    }

    /// Pull the user's own library — playlists and albums.
    ///
    /// Library requests, not catalog ones: this is "play my music", and it works for a
    /// downloaded/purchased library even without an active Apple Music subscription. Catalog
    /// search (below) is the part that needs the subscription.
    func loadLibrary() async {
        guard status == .authorized else { return }
        loading = true
        defer { loading = false }
        do {
            var playlistRequest = MusicLibraryRequest<Playlist>()
            playlistRequest.limit = 100
            playlists = try await playlistRequest.response().items

            var albumRequest = MusicLibraryRequest<Album>()
            albumRequest.limit = 100
            albumRequest.sort(by: \.libraryAddedDate, ascending: false)
            albums = try await albumRequest.response().items
        } catch {
            errorText = "Couldn't read your library: \(error.localizedDescription)"
        }
    }

    func search(_ term: String) async {
        let q = term.trimmingCharacters(in: .whitespacesAndNewlines)
        guard status == .authorized, !q.isEmpty else { searchResults = []; return }
        loading = true
        defer { loading = false }
        do {
            var request = MusicCatalogSearchRequest(term: q, types: [Song.self])
            request.limit = 25
            searchResults = try await request.response().songs
        } catch {
            errorText = "Search failed: \(error.localizedDescription)"
        }
    }

    func play<T: PlayableMusicItem>(_ item: T) async {
        do {
            player.queue = [item]
            try await player.play()
        } catch {
            errorText = "Couldn't play that: \(error.localizedDescription)"
        }
    }

    func togglePlayPause() async {
        do {
            if isPlaying { player.pause() } else { try await player.play() }
        } catch {
            errorText = "Playback failed: \(error.localizedDescription)"
        }
    }

    func skipForward() async { try? await player.skipToNextEntry() }
    func skipBackward() async { try? await player.skipToPreviousEntry() }
}

struct MusicPanelView: View {
    @State private var model = MusicModel()
    @State private var query = ""

    var body: some View {
        NavigationStack {
            Group {
                switch model.status {
                case .authorized:  library
                case .notDetermined: permissionPrompt
                default:           denied
                }
            }
            .navigationTitle("Music")
        }
        .safeAreaInset(edge: .bottom) {
            if model.nowPlayingTitle != nil { nowPlaying }
        }
        .task {
            if model.status == .authorized { await model.loadLibrary() }
        }
        .alert("Music", isPresented: .init(get: { model.errorText != nil },
                                           set: { if !$0 { model.errorText = nil } })) {
            Button("OK", role: .cancel) { model.errorText = nil }
        } message: {
            Text(model.errorText ?? "")
        }
    }

    private var permissionPrompt: some View {
        ContentUnavailableView {
            Label("Play your music here", systemImage: "music.note")
        } description: {
            Text("Float can play your Apple Music library without leaving the scene.")
        } actions: {
            Button("Allow Access") {
                Task { await model.requestAuthorization() }
            }
            .buttonStyle(.borderedProminent)
        }
    }

    private var denied: some View {
        ContentUnavailableView {
            Label("No access to Music", systemImage: "music.note")
        } description: {
            Text("Enable Media & Apple Music for Float in Settings → Privacy.")
        }
    }

    private var library: some View {
        List {
            if !model.searchResults.isEmpty {
                Section("Apple Music") {
                    ForEach(model.searchResults) { song in
                        Button {
                            Task { await model.play(song) }
                        } label: {
                            row(title: song.title, subtitle: song.artistName, art: song.artwork)
                        }
                    }
                }
            }
            Section("Playlists") {
                if model.playlists.isEmpty { Text("None").foregroundStyle(.secondary) }
                ForEach(model.playlists) { playlist in
                    Button {
                        Task { await model.play(playlist) }
                    } label: {
                        row(title: playlist.name,
                            subtitle: playlist.curatorName ?? "Playlist",
                            art: playlist.artwork)
                    }
                }
            }
            Section("Recently Added") {
                if model.albums.isEmpty { Text("None").foregroundStyle(.secondary) }
                ForEach(model.albums) { album in
                    Button {
                        Task { await model.play(album) }
                    } label: {
                        row(title: album.title, subtitle: album.artistName, art: album.artwork)
                    }
                }
            }
        }
        .searchable(text: $query, prompt: "Search Apple Music")
        .onSubmit(of: .search) {
            Task { await model.search(query) }
        }
        .overlay { if model.loading { ProgressView() } }
    }

    private func row(title: String, subtitle: String, art: Artwork?) -> some View {
        HStack(spacing: 12) {
            if let art {
                ArtworkImage(art, width: 44, height: 44)
                    .clipShape(RoundedRectangle(cornerRadius: 6))
            } else {
                RoundedRectangle(cornerRadius: 6)
                    .fill(.quaternary)
                    .frame(width: 44, height: 44)
            }
            VStack(alignment: .leading, spacing: 2) {
                Text(title).lineLimit(1)
                Text(subtitle).font(.caption).foregroundStyle(.secondary).lineLimit(1)
            }
        }
    }

    private var nowPlaying: some View {
        HStack(spacing: 18) {
            VStack(alignment: .leading, spacing: 2) {
                Text(model.nowPlayingTitle ?? "").font(.callout).lineLimit(1)
                if let sub = model.nowPlayingSubtitle {
                    Text(sub).font(.caption).foregroundStyle(.secondary).lineLimit(1)
                }
            }
            Spacer()
            Button { Task { await model.skipBackward() } } label: {
                Image(systemName: "backward.fill")
            }
            Button { Task { await model.togglePlayPause() } } label: {
                Image(systemName: model.isPlaying ? "pause.fill" : "play.fill")
            }
            Button { Task { await model.skipForward() } } label: {
                Image(systemName: "forward.fill")
            }
        }
        .buttonStyle(.plain)
        .padding(.horizontal, 20)
        .padding(.vertical, 14)
        .background(.regularMaterial)
    }
}

import SwiftUI
import AVKit
import PhotosUI

/// Entertainment sub-menu (reached from the launcher's "Entertainment" button). Collects the
/// non-scene activities: the web browser (which is where the Kindle lives, and every streaming
/// service that has a website), Apple Music played in-process, and local video.
///
/// Labels here name the SOURCE rather than the activity, because on visionOS what a button can
/// actually reach varies a lot by source and a vague "Video" sets the wrong expectation. See
/// `WatchSection` for the specific case.
struct EntertainmentMenuView: View {
    @Environment(\.openWindow) private var openWindow

    var body: some View {
        NavigationStack {
            List {
                Section("Read & Browse") {
                    Button {
                        openWindow(id: "browser")
                    } label: {
                        Label {
                            VStack(alignment: .leading, spacing: 2) {
                                Text("Web Browser")
                                Text("Kindle, streaming sites, anything else")
                                    .font(.caption).foregroundStyle(.secondary)
                            }
                        } icon: {
                            Image(systemName: "globe")
                        }
                    }
                }

                Section("Listen") {
                    Button {
                        openWindow(id: "music")
                    } label: {
                        Label {
                            VStack(alignment: .leading, spacing: 2) {
                                Text("Apple Music")
                                Text("Your library, played here in the scene")
                                    .font(.caption).foregroundStyle(.secondary)
                            }
                        } icon: {
                            Image(systemName: "music.note")
                        }
                    }
                }

                WatchSection(openWindow: openWindow)
            }
            .navigationTitle("Entertainment")
        }
        .frame(minWidth: 380, minHeight: 460)
    }
}

/// The "Watch" options, split by where the video actually comes from.
///
/// There is no public API for the Apple TV app's library. Purchases, rentals and TV+ titles are
/// FairPlay-protected and decrypt only inside the TV app itself; no third-party app can list
/// them, let alone play them. So this section offers the two routes that DO work — local video,
/// and tv.apple.com in the browser — and says which is which rather than offering a "TV
/// Library" button that could only ever fail.
private struct WatchSection: View {
    let openWindow: OpenWindowAction

    var body: some View {
        Section("Watch") {
            Button {
                openWindow(id: "video")
            } label: {
                Label {
                    VStack(alignment: .leading, spacing: 2) {
                        Text("Video from Photos")
                        Text("Anything in your own photo library")
                            .font(.caption).foregroundStyle(.secondary)
                    }
                } icon: {
                    Image(systemName: "film")
                }
            }

            Button {
                openWindow(id: "browser")
            } label: {
                Label {
                    VStack(alignment: .leading, spacing: 2) {
                        Text("Apple TV & streaming on the web")
                        Text("Opens the browser — TV app titles aren't reachable from here")
                            .font(.caption).foregroundStyle(.secondary)
                    }
                } icon: {
                    Image(systemName: "play.tv")
                }
            }
        }
    }
}

/// Local video playback in its own window, so it can be placed and sized independently of the
/// menu that launched it.
struct VideoPanelView: View {
    @State private var pickedVideo: PhotosPickerItem?
    @State private var player: AVPlayer?
    @State private var loading = false

    var body: some View {
        VStack(spacing: 0) {
            if let player {
                VideoPlayer(player: player)
            } else {
                ContentUnavailableView {
                    Label("Nothing playing", systemImage: "film")
                } description: {
                    Text("Pick a video from your photo library.")
                }
            }

            // User-selected media needs no photo-library entitlement — PhotosPicker runs out
            // of process and hands back only what was chosen.
            PhotosPicker(selection: $pickedVideo, matching: .videos) {
                Label(loading ? "Loading…" : "Choose Video", systemImage: "photo.on.rectangle")
            }
            .padding(16)
        }
        .onChange(of: pickedVideo) { _, item in
            guard let item else { return }
            loading = true
            Task {
                if let url = try? await item.loadTransferable(type: PickedVideo.self)?.url {
                    player = AVPlayer(url: url)
                    player?.play()
                }
                loading = false
            }
        }
    }
}

/// Copies a picked video out of the Photos sandbox into a temp file AVPlayer can stream.
private struct PickedVideo: Transferable {
    let url: URL
    static var transferRepresentation: some TransferRepresentation {
        FileRepresentation(contentType: .movie) { video in
            SentTransferredFile(video.url)
        } importing: { received in
            let dst = URL.temporaryDirectory.appendingPathComponent(
                "float-video-" + received.file.lastPathComponent)
            try? FileManager.default.removeItem(at: dst)
            try FileManager.default.copyItem(at: received.file, to: dst)
            return Self(url: dst)
        }
    }
}

