private func observe() {
    func bind<V>(_ keyPath: KeyPath<WKWebView, V> & Sendable,
                 _ apply: @escaping @MainActor (BrowserTab, V) -> Void) {
        observations.append(webView.observe(keyPath, options: [.initial, .new]) { view, _ in
            MainActor.assumeIsolated {
                apply(self, view[keyPath: keyPath])
            }
        })
    }
    bind(\.title)          { tab, v in if let v, !v.isEmpty { tab.title = v } }
    bind(\.url)            { tab, v in tab.urlString = v?.absoluteString ?? "" }
    bind(\.isLoading)      { tab, v in tab.isLoading = v }
    bind(\.estimatedProgress) { tab, v in tab.progress = v }
    bind(\.canGoBack)      { tab, v in tab.canGoBack = v }
    bind(\.canGoForward)   { tab, v in tab.canGoForward = v }
}

